  };

  for (const ligne of ctx.lignes ?? []) {
    plafondScore = 1;
    const sens = mm(ligne.debit) > 0 ? 'debit' : 'credit';
    const categorie = categories.find((c) => c.sens === sens && c.re.test(ligne.libelle));
