    const proches = base.filter((f) => APPROUVES.has(f.statut) && Math.abs(montant - reste(f)) <= tolerance);
    if (proches.length === 1) {
      const f = proches[0];
      proposer(ligne, 'ecart', [{ facture: f, montant: reste(f) }],
